import socket, threading, struct, time, re

def send_packet(conn, payload, seq):
    header = struct.pack("<I", len(payload))[:3] + bytes([seq])
    conn.sendall(header+payload)
def send_ok(conn, seq=1):
    send_packet(conn, b"\x00\x00\x00\x02\x00\x00\x00", seq)
def send_result(conn, columns, rows, seq_start=1, types=None):
    seq = seq_start
    send_packet(conn, bytes([len(columns)]), seq); seq+=1
    for idx, col in enumerate(columns):
        name = col.encode() if isinstance(col, str) else col
        payload = b"\x03def"+b"\x00"+b"\x00"+b"\x00"+bytes([len(name)])+name+bytes([len(name)])+name+struct.pack("<H",33)+struct.pack("<I",1024)+bytes([types[idx] if types and idx < len(types) else 0xfd])+struct.pack("<H",0)+b"\x00"+b"\x00\x00"
        send_packet(conn, payload, seq); seq+=1
    eof=b"\xfe\x00\x00\x02\x00"
    send_packet(conn, eof, seq); seq+=1
    for row in rows:
        p=b""
        for val in row:
            if val is None:
                p+=b"\xfb"
            else:
                if isinstance(val,str): val=val.encode()
                elif isinstance(val,int): val=str(val).encode()
                if len(val)<251: p+=bytes([len(val)])+val
                elif len(val)<65536: p+=b"\xfc"+struct.pack("<H",len(val))+val
                else: p+=b"\xfd"+struct.pack("<I",len(val))[:3]+val
        send_packet(conn, p, seq); seq+=1
    send_packet(conn, eof, seq); seq+=1
    return seq

