                elif "select release_lock" in qlower: send_result(c, ["RELEASE_LOCK"], [["1"]],1,[0x03])
                elif "select 1" in qlower and "information_schema.schemata" in qlower and "_skeema_tmp" in query:
                    if "_skeema_tmp" in schemas: send_result(c, ["1"], [["1"]],1,[0x03])
