                    print(f" -> returning {len(rows)} rows",flush=True)
                    send_result(c, ["schema_name","default_character_set_name","default_collation_name"], rows,1)
                elif "information_schema.schemata" in qlower:
                    print(" -> generic schemata",flush=True)
                    m=re.search(r"schema_name\s*=\s*'([^']+)'",query,re.I)
