                        if sel_match:
                            sel=sel_match.group(1)
                            if sel.strip()=="1":
                                rows=[["1"]] if req in schemas else []
                                send_result(c, ["1"], rows,1,[0x03])
                            else:
                                sel_clean=re.sub(r"sql_buffer_result\s+","",sel,flags=re.I);sel_clean=re.sub(r"distinct\s+","",sel_clean,flags=re.I)
                                ncols=sel_clean.count(",")+1
                                print(f" -> ncols {ncols}",flush=True)
                                if ncols==3:
                                    rows=[]
                                    if req in schemas: rows.append([req,schemas[req][0],schemas[req][1]])
                                    send_result(c, ["schema_name","default_character_set_name","default_collation_name"],rows,1)
                                else:
                                    send_result(c, [f"c{i}" for i in range(ncols)],[],1)
                        else: send_result(c, ["schema_name"],[],1)
                    else:
                        rows=[[k,v[0],v[1]] for k,v in schemas.items()]
                        send_result(c, ["schema_name","default_character_set_name","default_collation_name"],rows,1)
                elif "information_schema.partitions" in qlower:
                    send_result(c, ["table_name","partition_name","partition_method","subpartition_method","partition_ordinal_position","data_length"],[],1)
                elif "information_schema.tables" in qlower:
                    print(" -> tables",flush=True)
                    sel_match=re.search(r"select\s+(.*?)\s+from",query,re.I|re.S)
                    if sel_match:
                        sel=sel_match.group(1);sel_clean=re.sub(r"sql_buffer_result\s+","",sel,flags=re.I);sel_clean=re.sub(r"distinct\s+","",sel_clean,flags=re.I)
                        ncols=sel_clean.count(",")+1
                        print(f" -> ncols {ncols} sel {sel_clean[:300]}",flush=True)
                        send_result(c, [f"c{i}" for i in range(ncols)],[],1)
                    else: send_result(c, ["c1"],[],1)
                elif "information_schema.routines" in qlower or "information_schema.parameters" in qlower or "information_schema.events" in qlower or "information_schema.triggers" in qlower or "information_schema.views" in qlower:
                    sel_match=re.search(r"select\s+(.*?)\s+from",query,re.I|re.S)
                    if sel_match:
                        sel=sel_match.group(1);sel_clean=re.sub(r"sql_buffer_result\s+","",sel,flags=re.I)
                        ncols=sel_clean.count(",")+1
                        send_result(c, [f"c{i}" for i in range(ncols)],[],1)
                    else: send_result(c, ["c1"],[],1)
                elif qlower.startswith("show full tables"):
                    send_result(c, ["Tables","Table_type"],[],1)
                elif qlower.startswith("show create table"):
                    send_packet(c, b"\xff"+struct.pack("<H",1146)+b"#42S02"+b"Table doesn't exist",1)
                elif qlower.startswith("show table status"):
                    send_result(c, [f"c{i}" for i in range(18)],[],1)
                elif qnorm.startswith("drop database"):
                    m2=re.search(r"drop database\s+`?([^`\s]+)`?",query,re.I)
                    if m2: schemas.pop(m2.group(1),None);tables.pop(m2.group(1),None);print(f"DROP {m2.group(1)}",flush=True)
                    send_ok(c,seq=1)
