// Parse bool value string (for --bool=value)
// Returns true/false based on observed logic: trim spaces/tabs, lower, if "", "0", "false", "off" => false, else true.
func parseBoolValue(s string) bool {
	t := strings.Trim(s, " \t\r\n")
	l := strings.ToLower(t)
	if l == "" || l == "0" || l == "false" || l == "off" {
		return false
	}
	return true
}
