	if err != nil {
		return nil, ""
	}
	defer f.Close()
	vals := make(map[string]string)
	currentSection := ""
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		line = strings.TrimSuffix(line, "\r")
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") {
			end := strings.Index(line, "]")
			if end == -1 {
				continue // ignore malformed section? Or error? Probably ignore.
			}
			currentSection = strings.TrimSpace(line[1:end])
			continue
		}
		if currentSection != "client" {
			continue
		}
		// Strip trailing # or ; comments? For my.cnf, both # and ; start comments? Probably. Let's strip both.
		if idx := strings.Index(line, "#"); idx != -1 {
			line = strings.TrimSpace(line[:idx])
		}
		if idx := strings.Index(line, ";"); idx != -1 {
			// Only strip ; if preceded by space? Or always? For simplicity, always strip.
			line = strings.TrimSpace(line[:idx])
		}
		if idx := strings.Index(line, "="); idx != -1 {
			key := strings.TrimSpace(line[:idx])
			val := strings.TrimSpace(line[idx+1:])
			// Strip quotes?
			if len(val) >= 2 && ((strings.HasPrefix(val, "\"") && strings.HasSuffix(val, "\"")) || (strings.HasPrefix(val, "'") && strings.HasSuffix(val, "'"))) {
				val = val[1 : len(val)-1]
			}
			// Only user/password? Actually also check for other keys? Ignore others.
			if key == "user" || key == "password" {
				vals[key] = val
			}
		} else {
			// No =, key alone? For my.cnf, key alone without value? Probably ignore.
			continue
		}
	}
	return vals, ""
}
