				continue
			}
			base := k
			isSkipOrig := false
			if strings.HasPrefix(k, "skip-") {
				base = strings.TrimPrefix(k, "skip-")
				isSkipOrig = true
			}
			_ = isSkipOrig
			if isBoolOption(base) || base == "debug" {
				b := false
				if strings.HasPrefix(k, "skip-") {
					if v == "\x00PROMPT\x00" {
						b = false
					} else {
						parsedVal := parseBoolValue(v)
						b = !parsedVal
					}
				} else {
					if v == "true" && true {
					}
					// For bool without = (stored as "true") vs with =value (stored as raw value like "true"/"false"/"foo"/""/etc.)
					// Our parse stores bool without = as "true" (for base without skip-) or "false" (for skip- without =, stored under base with "false").
