				} else if kv.isSkip {
					outLines = append(outLines, kv.key)
				} else if isBoolOption(kv.base) || kv.base == "debug" {
					outLines = append(outLines, kv.key)
				} else {
					if kv.val == "" {
						outLines = append(outLines, kv.key)
					} else {
						outLines = append(outLines, fmt.Sprintf("%s=%s", kv.key, kv.val))
					}
				}
			}
			firstSection = false
		} else {
			if !firstSection {
				outLines = append(outLines, "")
			}
			outLines = append(outLines, fmt.Sprintf("[%s]", secName))
			for _, kv := range list {
				if kv.val == "\x00PROMPT\x00" {
					outLines = append(outLines, kv.key)
				} else if kv.isSkip {
					outLines = append(outLines, kv.key)
				} else if isBoolOption(kv.base) || kv.base == "debug" {
