		}
		return 2
	}
	logWarn(fmt.Sprintf("Unable to automatically determine database server's vendor/version. To set manually, use the \"flavor\" option in %s", skeemaPath))
	logInfo(fmt.Sprintf("Added environment [%s] to %s", env, skeemaPath))
	if parsed.debug {
		logDebug("Exit code 0 (SUCCESS)")
	}
	return 0
}
