func isValidCreateStatement(stmtText string) bool {
	matched, _ := regexp.MatchString(`(?i)\bCREATE\b\s+TABLE\b`, stmtText)
	if matched {
		return true
	}
	matched, _ = regexp.MatchString(`(?i)\bCREATE\b.*\bPROCEDURE\b`, stmtText)
	if matched {
		return true
	}
	matched, _ = regexp.MatchString(`(?i)\bCREATE\b.*\bFUNCTION\b`, stmtText)
	if matched {
		return true
	}
	return false
}

func isIgnoredStatement(stmtText string) bool {
	trimmed := strings.TrimSpace(stmtText)
	if trimmed == "" {
		return true
	}
	upper := strings.ToUpper(trimmed)
	if strings.HasPrefix(upper, "USE ") || upper == "USE" {
		return true
	}
	fields := strings.Fields(upper)
	if len(fields) > 0 && fields[0] == "DELIMITER" {
		return true
	}
	if strings.HasPrefix(upper, "START TRANSACTION") {
		return true
	}
	if len(fields) > 0 {
		if fields[0] == "BEGIN" || fields[0] == "COMMIT" || fields[0] == "ROLLBACK" {
			return true
		}
	}
	return false
}
