func runFormat(parsed *ParsedCLI) int {
	checkOnly := false
	if v, ok := parsed.options["write"]; ok && v == "false" {
		checkOnly = true
	}
	verb := "Reformatting"
	if checkOnly {
		verb = "Checking format of"
	}
	cwd, _ := os.Getwd()
	env := "production"
	if len(parsed.positionals) > 0 {
		env = parsed.positionals[0]
	}
	type finfo struct {
		path     string
		isSchema bool
		hasValid bool
	}
	var orderedDirs []string
	finfos := make(map[string]*finfo)
	var walk func(dir string)
	walk = func(dir string) {
		orderedDirs = append(orderedDirs, dir)
		isSchema := isSchemaDir(dir, env)
		sqlFiles := listSQLFiles(dir)
		hasValid := false
		for _, f := range sqlFiles {
			content, err := os.ReadFile(f)
			if err != nil {
				continue
			}
			stmts := parseSQLStatements(string(content))
			for _, st := range stmts {
				if isIgnoredStatement(st.text) {
					continue
				}
				if isValidCreateStatement(st.text) {
					hasValid = true
					break
				}
			}
			if hasValid {
				break
			}
		}
		finfos[dir] = &finfo{path: dir, isSchema: isSchema, hasValid: hasValid}
		if isSchema || hasValid {
			return
		}
		entries, err := os.ReadDir(dir)
		if err != nil {
			return
		}
		var subdirs []string
		for _, e := range entries {
			if e.IsDir() {
				name := e.Name()
				if strings.HasPrefix(name, ".") {
					continue
				}
				subdirs = append(subdirs, name)
			}
		}
		for i := 1; i < len(subdirs); i++ {
			for j := i; j > 0 && subdirs[j] < subdirs[j-1]; j-- {
				subdirs[j], subdirs[j-1] = subdirs[j-1], subdirs[j]
			}
		}
		for _, sub := range subdirs {
			walk(dir + "/" + sub)
		}
	}
	walk(cwd)
	var failures int
	for _, dir := range orderedDirs {
		logInfo(fmt.Sprintf("%s %s", verb, dir))
		fi := finfos[dir]
		if fi == nil {
			continue
		}
		if !fi.isSchema && !fi.hasValid {
			continue
		}
		values, explicit, errStr := loadConfigForDir(dir, env, parsed.options)
		if errStr != "" {
			logError(fmt.Sprintf("Skipping %s: %s", dir, errStr))
			failures++
			continue
		}
		hasRegexErr := false
		for _, optName := range []string{"ignore-table", "ignore-schema", "ignore-proc", "ignore-func"} {
			if val, ok := values[optName]; ok && val != "" {
				if _, err := regexp.Compile(val); err != nil {
					logError(fmt.Sprintf("Skipping %s: Invalid regexp for option %s: %s", dir, optName, val))
					failures++
					hasRegexErr = true
					break
				}
			}
		}
		if hasRegexErr {
			continue
		}
		if errMsg := validateConnectionOptions(values); errMsg != "" {
			logError(fmt.Sprintf("Skipping %s: %s", dir, errMsg))
			failures++
			continue
		}
		hosts, hostErr := resolveHosts(dir, env, values, explicit, parsed.options)
		if hostErr != "" {
			if hostErr == "NOHOST" {
				logError(fmt.Sprintf("Skipping %s: This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment \"%s\"", dir, env))
				failures++
				continue
			}
			if hostErr == "EMPTYHOSTWRAPPER" {
				logWarn(fmt.Sprintf("Skipping %s: directory maps to an empty list of database servers", dir))
				logWarn("The host-wrapper option controls which hosts this directory maps to, but the executed script returned no hostnames.")
				continue
			}
			if strings.HasPrefix(hostErr, "WARN:") {
				msg := strings.TrimPrefix(hostErr, "WARN:")
				for _, line := range strings.Split(msg, "\n") {
					if line != "" {
						logWarn(line)
					}
				}
				continue
			}
			logError(fmt.Sprintf("Skipping %s: %s", dir, hostErr))
			failures++
			continue
		}
		if len(hosts) == 0 {
			continue
		}
		for _, h := range hosts {
			portStr := ""
			socketStr := ""
			portExplicit := false
			socketExplicit := false
			if v, ok := values["port"]; ok {
				portStr = stripQuotes(v)
				if exp, ok2 := explicit["port"]; ok2 && exp {
					portExplicit = true
				}
			}
			if v, ok := values["socket"]; ok {
				socketStr = stripQuotes(v)
				if exp, ok2 := explicit["socket"]; ok2 && exp {
					socketExplicit = true
				}
			}
			hStripped := stripQuotes(h)
			network, address, display := resolveConnection(hStripped, portStr, socketStr, portExplicit, socketExplicit)
			conn, err := net.Dial(network, address)
			if err != nil {
				logError(fmt.Sprintf("Skipping %s: Unable to connect to %s for %s: %s", dir, display, dir, err.Error()))
				failures++
				continue
			}
			conn.Close()
		}
	}
	if failures > 0 {
		if parsed.debug {
			logDebug("Exit code 78")
		}
		return 78
	}
	if parsed.debug {
		logDebug("Exit code 0")
	}
	return 0
}
